<!doctype html><html><head><meta charset=utf-8><style>body{font-family:DejaVu Sans;color:#172033;font-size:12px}.head{border-bottom:3px solid #06b6d4;padding-bottom:18px}.brand{font-size:28px;font-weight:bold}.cyan{color:#0891b2}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{padding:10px;border-bottom:1px solid #dbe3ec;text-align:left}.totals{width:45%;margin-left:auto}.right{text-align:right}.badge{display:inline-block;padding:5px 10px;background:#e6fbff;color:#087c91}</style></head><body><div class=head><div class=brand>TECHNO<span class=cyan>OUT</span></div><div>{{ strtoupper($type) }} · {{ $document->number }}</div></div><p><strong>For:</strong> {{ $document->customer_name }} {{ $document->customer_company ? '— '.$document->customer_company : '' }}<br>{{ $document->customer_email }}</p><p><span class=badge>{{ strtoupper($document->status) }}</span></p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th class=right>Total</th></tr></thead><tbody>@foreach($document->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>{{ $document->currency }} {{ number_format($item->unit_price,2) }}</td><td class=right>{{ $document->currency }} {{ number_format($item->total,2) }}</td></tr>@endforeach</tbody></table><table class=totals><tr><th>Subtotal</th><td class=right>{{ number_format($document->subtotal,2) }}</td></tr><tr><th>Discount</th><td class=right>{{ number_format($document->discount,2) }}</td></tr><tr><th>Tax</th><td class=right>{{ number_format($document->tax,2) }}</td></tr><tr><th>Total</th><td class=right><strong>{{ $document->currency }} {{ number_format($document->total,2) }}</strong></td></tr></table><p>{{ $document->terms }}</p></body></html>
